resource "aws_s3_bucket" "log_bucket" {
  bucket              = local.log_bucket_name
  object_lock_enabled = true

  tags = merge(local.common_tags, {
    Name          = local.log_bucket_name
    N2SF_Control  = "AuditLog,DU,DT"
    N2SF_Resource = "LogBucket"
  })
}

resource "aws_s3_bucket_policy" "log_bucket_policy" {
  bucket = aws_s3_bucket.log_bucket.id
  policy = data.aws_iam_policy_document.log_bucket_policy_doc.json

  depends_on = [
    aws_s3_bucket_public_access_block.log_bucket_pab
  ]

resource "aws_secretsmanager_secret" "payment_app_secret" {
  name        = "${local.name_prefix}/payment-app"
  description = "Secret placeholder for payment application integration"
  kms_key_id  = aws_kms_key.payment_key.arn

  recovery_window_in_days = 30

  tags = merge(local.common_tags, {
    Name         = "${local.name_prefix}-payment-app-secret"
    N2SF_Control = "AC,DU,EK"
  })

resource "aws_security_group" "api_sg" {
  name        = "${local.name_prefix}-api-sg"
  description = "Security group for payment API boundary"
  vpc_id      = aws_vpc.payments_vpc.id

  ingress {
    description = "Allow HTTPS from approved external range"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.allowed_api_cidr]
  }

