    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name         = "${local.name_prefix}-api-sg"
    N2SF_Control = "EB,IF,RA"
  })
}

